import React from 'react';
import { createNativeStackNavigator } from '@react-navigation/native-stack';

import SplashLogoScreen from '../screens/SplashLogoScreen';
import TelaLogin from '../screens/Login';
import TelaCadastro from '../screens/Cadastro';

export type RotasAutenticacao = {
  SplashLogo: undefined;
  Login: undefined;
  Cadastro: undefined;
};

const Stack = createNativeStackNavigator<RotasAutenticacao>();

export default function AuthNavigator(): JSX.Element {
  return (
    <Stack.Navigator
      initialRouteName="SplashLogo"
      screenOptions={{ headerShown: false }}
    >
      <Stack.Screen name="SplashLogo" component={SplashLogoScreen} />
      <Stack.Screen name="Login" component={TelaLogin} />
      <Stack.Screen
        name="Cadastro"
        component={TelaCadastro}
        options={{ gestureEnabled: true }}
      />
    </Stack.Navigator>
  );
}